import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import {spawn} from 'node:child_process';
import net from 'node:net';
const root=new URL('.',import.meta.url).pathname;
const {sourceFixture,installNetworkGuard}=await import(pathToFileURL('/home/nearby/.t3/worktrees/JoshBot/t3-d3eb9bf1/scripts/bench-agent-release.mjs').href);
const guard=installNetworkGuard({loopback:true});
const [variant,mode,latency='0']=process.argv.slice(2), delayMs=Number(latency);
const load=(name:string)=>import(pathToFileURL(root+variant+'/lib/agent-features/'+name+'.ts').href);
const api={...await load('services'),...await load('runtime'),...await load('bounded-context'),...await load('budgets'),...await load('calendar/ics')};
const f=sourceFixture(api,mode==='adapter-six'?mode:'consumer');
const owner={teamId:'TBENCH',userId:'UBENCH',channelId:'CBENCH'},now=new Date('2026-10-22T12:00:00Z');
let server:any,client:any,productionClient:any;
let get=0,batch=0,index=0,auth=0,writes=0,phases=0,active=0,peak=0;const phasesMs:number[]=[];
const pause=(ms:number)=>new Promise(r=>setTimeout(r,ms));
const io=async(work:()=>Promise<any>)=>{phases++;active++;peak=Math.max(peak,active);const t=performance.now();try{if(delayMs)await pause(delayMs);return await work();}finally{active--;phasesMs.push(performance.now()-t);}};
const parse=(info:string)=>Object.fromEntries(info.split('\r\n').flatMap(line=>{const m=line.match(/^cmdstat_([^:]+):calls=(\d+)/);return m?[[m[1],Number(m[2])]]:[]}));
const cpu=(info:string)=>Object.fromEntries(info.split('\r\n').flatMap(line=>{const m=line.match(/^(used_cpu_(?:user|sys)):(.*)/);return m?[[m[1],Number(m[2])]]:[]}));
try{
const sock=net.createServer();await new Promise<void>(r=>sock.listen({port:0,host:'127.0.0.1'},r));const port=(sock.address() as any).port;await new Promise(r=>sock.close(r));
server=spawn('/tmp/joshbot-poll-redis/redis-7.2.10/src/redis-server',['--bind','127.0.0.1','--port',String(port),'--save','','--appendonly','no','--dir',root],{stdio:['ignore','pipe','pipe']});
await new Promise<void>((resolve,reject)=>{server.stdout.on('data',(d:Buffer)=>{if(d.toString().includes('Ready to accept connections'))resolve();});server.once('exit',reject);});
const {createClient}=await import('redis');const url=`redis://127.0.0.1:${port}`;client=createClient({url,socket:{reconnectStrategy:false}});client.on('error',()=>{});await client.connect();
for(const [key,value] of f.backend.data)await client.set(key,value);
const sources=[['follow-ups:user:','follow-ups:record:'],['schedules:user:','schedules:job:'],['monitors:user:','monitors:job:'],['channel-digests:user:','channel-digests:subscription:']];
for(const [prefix,record] of sources){const ids=Array.from({length:200},(_,i)=>`job-${i}`).filter(id=>f.backend.data.has(record+id));if(ids.length)await client.sAdd(prefix+owner.userId,ids);}
process.env.REDIS_URL=url;
const actual=await(await load('store')).createAgentStateBackend();assert.ok(actual);
productionClient=await(await import(pathToFileURL(root+variant+'/lib/redis.ts').href)).getRedisClient();
f.backend.get=async(key:string)=>{get++;return io(()=>actual.get(key));};
f.backend.compareSet=async(key:string,previous:string|null,next:string,ttl?:number)=>{
 // Receipt/store writes are actual default Redis CAS too, with counters separate from read phases.
 const ok=await actual.compareSet(key,previous,next,ttl);if(ok){writes++;f.backend.data.set(key,next);}return ok;
};
if(actual.getMany)f.backend.getMany=async(keys:string[],max:number)=>{batch++;return io(()=>actual.getMany(keys,max));};
const adapters=api.createProductionContextAdapters({redis:async()=>({eval:async(...args:any[])=>{index++;return io(()=>client.eval(...args));}}),evaluateAccess:async()=>{auth++;return io(async()=>({allowed:true}));}});
const controller=new AbortController();
const target=mode==='adapter-six'?{id:'research-probe',help:'probe',execute:async(_:string,ctx:any)=>{const items=await api.readBoundedContext(ctx,['note','goal','habit','journal','bookmark','follow-up','reminder','monitor','digest','artifact','memory','event']);assert.equal(items.length,1500);return '1500 complete';}}:(await load(mode)).default;
const service=api.createAgentFeatureServices(f.backend,owner,controller.signal,{now,timezone:'UTC',featureId:target.id},adapters);
const captured:any[]=[];const read=service.readContext;service.readContext=async(kinds:any)=>{const out=await read(kinds);captured.push(out);return out;};service.generate=service.search=async()=>{throw new Error('forbidden provider');};
const statsBefore=parse(await client.info('commandstats')),cpuBefore=cpu(await client.info('cpu'));
const usedBefore=process.cpuUsage(),t=performance.now();const reply=await api.runAgentFeature(target,mode==='meeting-prep'?'prepare Atlas | purpose: Review launch':mode==='morning-brief'?'brief':'review',owner,{backend:f.backend,now,timezone:'UTC',signal:controller.signal,services:service});
const wallMs=performance.now()-t,used=process.cpuUsage(usedBefore),rssMiB=process.memoryUsage().rss/1048576,peakRssMiB=Number(readFileSync('/proc/self/status','utf8').match(/^VmHWM:\s+(\d+)/m)![1])/1024;
const cpuAfter=cpu(await client.info('cpu')),statsAfter=parse(await client.info('commandstats'));
assert.equal(active,0);assert.match(reply,mode==='adapter-six'?/^1500 complete/:mode==='meeting-prep'?/mp-/:mode==='morning-brief'?/Morning brief/i:/wr-/);
const bytes=captured.map(x=>api.measureAgentContext(x));assert.ok(bytes.every(x=>x<=16*1048576));assert.ok(bytes.reduce((a,b)=>a+b,0)<32*1048576);
const commands=Object.fromEntries(Object.entries(statsAfter).map(([k,v])=>[k,v-(statsBefore[k]??0)]).filter(([k,v])=>k!=='info'&&v));
const normalize=(s:string)=>s.replace(/\b(?:mp|wr)-[0-9a-f-]{36}\b/g,'<generated-id>');
const saved=[...f.backend.data].filter(([k]:[string,string])=>k.startsWith('nobo:agents:')).map(([k,v]:[string,string])=>[k,normalize(v)]);
const sorted=phasesMs.sort((a,b)=>a-b);
console.log(JSON.stringify({variant,mode,delayMs,wallMs,cpuMs:(used.user+used.system)/1000,rssMiB,peakRssMiB,redisCpuMs:((cpuAfter.used_cpu_user-cpuBefore.used_cpu_user)+(cpuAfter.used_cpu_sys-cpuBefore.used_cpu_sys))*1000,commands,ordinaryGets:get,batches:batch,index,auth,readPhases:phases,peak,phaseMedianMs:sorted[Math.floor(sorted.length/2)],phaseP95Ms:sorted[Math.ceil(sorted.length*.95)-1],counts:captured.map(x=>x.length),bytes,totalBytes:bytes.reduce((a,b)=>a+b,0),sourceHash:createHash('sha256').update(JSON.stringify(captured)).digest('hex'),savedHash:createHash('sha256').update(JSON.stringify(saved)).digest('hex'),replyHash:createHash('sha256').update(normalize(reply)).digest('hex'),writes,blocked:guard.blocked}));
}finally{if(productionClient?.isOpen)await productionClient.quit();if(client?.isOpen)await client.quit();if(server){server.kill('SIGTERM');await new Promise(r=>server.once('exit',r));}guard.restore();}
